import torchimport torch.nn as nnimport numpy as npimport matplotlib.pyplot as pltclass MLP(nn.Module):    def __init__(self, input_dim, output_dim, hidden_layers):        super(MLP, self).__init__()        layers = []        layers.append(nn.Linear(input_dim, hidden_layers[0]))        layers.append(nn.Tanh())                for i in range(len(hidden_layers) - 1):            layers.append(nn.Linear(hidden_layers[i], hidden_layers[i + 1]))            layers.append(nn.Tanh())                layers.append(nn.Linear(hidden_layers[-1], output_dim))        self.model = nn.Sequential(*layers)        def forward(self, x):        return self.model(x)